/* ==========================================================================
   인게임 6슬롯 코스메틱 뷰 스타일 (Cosmetics View CSS)
   ========================================================================== */

/* 1. 배너 카드 기본 규격 및 격리 */
.player-banner, .pb-card {
  --banner-ink: #302418;
  --banner-accent: #795520;
  --banner-bg: #eee2c9;
  --frame-gold-edge: #b58a41;
  --frame-gold-shine: #f4d890;
  position: absolute;
  display: flex;
  align-items: center;
  width: min(330px, calc(100vw - 28px));
  aspect-ratio: 3 / 1;
  container-type: inline-size;
  isolation: isolate;
  border-radius: 6px;
  overflow: visible;
  user-select: none;
  pointer-events: none;
  box-sizing: border-box;
  padding: 0;
  background: transparent;
}

/* 2. 배경 레이어 (3:1 비율) */
.pb-layer-background {
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: 6px;
  overflow: hidden;
  background-color: var(--banner-bg);
  background-position: center;
  background-size: 100% 100%;
  background-repeat: no-repeat;
  transition: inset 0.15s ease, border-radius 0.15s ease;
}

/* 텍스트와 배지의 가독성을 위한 우아한 그라디언트 오버레이 */
.pb-layer-background::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(232, 218, 190, 0.45) 0%, rgba(239, 226, 202, 0.7) 26%, rgba(244, 235, 218, 0.8) 50%, rgba(244, 235, 218, 0.5) 100%);
  pointer-events: none;
}

/* 6개 기본 테마별 배경색 및 오버레이 */
.player-banner[data-theme="slate"] .pb-layer-background,
.pb-card[data-theme="slate"] .pb-layer-background {
  --banner-ink: #172c43;
  --banner-accent: #35506e;
  --banner-bg: #dce5f0;
}
.player-banner[data-theme="slate"] .pb-layer-background::after,
.pb-card[data-theme="slate"] .pb-layer-background::after {
  background: linear-gradient(90deg, rgba(220, 229, 240, 0.4) 0%, rgba(220, 229, 240, 0.7) 35%, rgba(220, 229, 240, 0.45) 100%);
}

.player-banner[data-theme="forest"] .pb-layer-background,
.pb-card[data-theme="forest"] .pb-layer-background {
  --banner-ink: #25351e;
  --banner-accent: #3d542d;
  --banner-bg: #e1e7cb;
}
.player-banner[data-theme="forest"] .pb-layer-background::after,
.pb-card[data-theme="forest"] .pb-layer-background::after {
  background: linear-gradient(90deg, rgba(225, 231, 203, 0.4) 0%, rgba(225, 231, 203, 0.7) 35%, rgba(225, 231, 203, 0.45) 100%);
}

.player-banner[data-theme="banner_cosmic_knight"] .pb-layer-background,
.pb-card[data-theme="banner_cosmic_knight"] .pb-layer-background {
  --banner-ink: #f8fafc;
  --banner-accent: #818cf8;
  --banner-bg: #0f172a;
}
.player-banner[data-theme="banner_cosmic_knight"] .pb-layer-background::after,
.pb-card[data-theme="banner_cosmic_knight"] .pb-layer-background::after {
  background: linear-gradient(90deg, rgba(15, 23, 42, 0.5) 0%, rgba(15, 23, 42, 0.75) 40%, rgba(15, 23, 42, 0.4) 100%);
}

.player-banner[data-theme="banner_crimson_sun"] .pb-layer-background,
.pb-card[data-theme="banner_crimson_sun"] .pb-layer-background {
  --banner-ink: #fff1f2;
  --banner-accent: #fb7185;
  --banner-bg: #1c1917;
}
.player-banner[data-theme="banner_crimson_sun"] .pb-layer-background::after,
.pb-card[data-theme="banner_crimson_sun"] .pb-layer-background::after {
  background: linear-gradient(90deg, rgba(28, 25, 23, 0.5) 0%, rgba(28, 25, 23, 0.75) 40%, rgba(28, 25, 23, 0.4) 100%);
}

.player-banner[data-theme="banner_hidden_myeongnyang"] .pb-layer-background,
.pb-card[data-theme="banner_hidden_myeongnyang"] .pb-layer-background {
  --banner-ink: #f0fdfa;
  --banner-accent: #2dd4bf;
  --banner-bg: #042f2e;
}
.player-banner[data-theme="banner_hidden_myeongnyang"] .pb-layer-background::after,
.pb-card[data-theme="banner_hidden_myeongnyang"] .pb-layer-background::after {
  background: linear-gradient(90deg, rgba(4, 47, 46, 0.5) 0%, rgba(4, 47, 46, 0.75) 40%, rgba(4, 47, 46, 0.4) 100%);
}

.player-banner[data-theme="plain"],
.pb-card[data-theme="plain"] {
  --banner-ink: #f1f5f9;
  --banner-accent: #94a3b8;
  --banner-bg: #273344;
}
.player-banner[data-theme="plain"] .pb-layer-background,
.pb-card[data-theme="plain"] .pb-layer-background {
  background-image: none !important;
  background-color: #273344;
}
.player-banner[data-theme="plain"] .pb-layer-background::after,
.pb-card[data-theme="plain"] .pb-layer-background::after {
  display: none;
}

/* 3. 배경 프레임 레이어 (외곽 테두리 & 황금 레일) */
.pb-layer-frame {
  position: absolute;
  inset: 0;
  z-index: 4;
  overflow: visible;
  pointer-events: none;
}
.pb-frame-img {
  position: absolute;
  left: -1%;
  top: -24%;
  width: 102%;
  height: 160%;
  object-fit: fill;
  pointer-events: none;
  display: block;
}
.pb-frame-fallback {
  position: absolute;
  inset: 0;
  border: 2px solid var(--frame-gold-edge);
  border-radius: 6px;
  display: none;
  box-shadow: inset 0 0 4px rgba(212, 175, 55, 0.4);
}

/* 프레임이 활성화되었을 때 배경을 황금 레일 안쪽으로 축소 맞춤 */
.player-banner[data-has-frame="true"] .pb-layer-background,
.pb-card[data-has-frame="true"] .pb-layer-background {
  inset: 8% 5% 6%;
  border-radius: 2px;
}

/* 숙련도 올클리어 골드 프레임 효과 */
.player-banner[data-frame-style="mastery-complete"] .pb-frame-img,
.pb-card[data-frame-style="mastery-complete"] .pb-frame-img {
  filter: drop-shadow(0 0 6px rgba(244, 216, 144, 0.65)) brightness(1.08);
}

/* 4. 배지 레이어 (좌측 독립 구획) */
.pb-layer-badge,
.pb-layer-badgeframe {
  position: absolute;
  left: 12%;
  top: 50%;
  transform: translateY(-50%);
  width: 15%;
  aspect-ratio: 1;
  border-radius: 50%;
  box-sizing: border-box;
}

.pb-layer-badge {
  z-index: 2;
  background: #382816;
  padding: 3px;
  display: grid;
  place-items: center;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.35);
  overflow: hidden;
}

.pb-badge-img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}

.pb-badge-glyph {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  font-size: 18px;
  line-height: 1;
  color: #ffe7a3;
  text-shadow: 0 1px 2px rgba(0,0,0,0.8);
}

.pb-badge-fallback-svg {
  width: 80%;
  height: 80%;
  display: none;
}

/* 5. 배지 프레임 (CSS 네이티브 링) */
.pb-layer-badgeframe {
  z-index: 3;
  pointer-events: none;
  border: 2px solid var(--frame-gold-edge);
  outline: 1px solid var(--frame-gold-shine);
  outline-offset: 1px;
}
.pb-layer-badgeframe[data-frame="silver"] {
  border-color: #a4b8cf;
  outline-color: #eef5ff;
}
.pb-layer-badgeframe[data-frame="violet"] {
  border-color: #b986d7;
  outline-color: #f1d9ff;
}

/* 6. 텍스트 및 정보 콘텐츠 (우측 영역, 3단 위계) */
.pb-layer-content,
.player-banner-text {
  position: absolute;
  left: 32%;
  right: 14%;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  z-index: 3;
  color: var(--banner-ink);
  pointer-events: none;
}

/* 배지가 숨겨졌을 때 텍스트 영역 좌측 여백 확장 */
.player-banner[data-badge-visible="false"] .player-banner-text,
.pb-card[data-badge-visible="false"] .pb-layer-content {
  left: 14%;
}

/* 1위계: 닉네임 (가장 강조) */
.pb-name,
.player-banner-name {
  font-size: 16px;
  line-height: 1.25;
  font-weight: 800;
  color: var(--banner-ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 2위계: 티어 (중간 크기, 부차적 정보) */
.pb-tier,
.player-banner-detail {
  font-size: 12px;
  line-height: 1.25;
  font-weight: 600;
  color: var(--banner-ink);
  opacity: 0.88;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 3위계: 칭호 (단독 장식 플레이트) */
.pb-title-plate {
  --title-edge: #bc904a;
  --title-ink: #ffe6b2;
  --title-fill: #322316;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 600;
  color: var(--banner-accent);
  padding: 1px 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
  display: inline-block;
}

/* 칭호 프레임 스타일링 (CSS-native) */
.pb-title-plate[data-frame]:not([data-frame="none"]):not([data-frame=""]) {
  color: var(--title-ink);
  background: var(--title-fill);
  border: 1px solid var(--title-edge);
  border-radius: 3px;
  box-shadow: inset 0 0 0 1px var(--title-fill), inset 0 0 0 2px color-mix(in srgb, var(--title-edge) 45%, transparent);
  padding: 2px 7px;
  width: fit-content;
}

.pb-title-plate[data-frame="silver"] {
  --title-edge: #a4b8cf;
  --title-ink: #eef5ff;
  --title-fill: #1d2c40;
}

.pb-title-plate[data-frame="violet"] {
  --title-edge: #b986d7;
  --title-ink: #f1d9ff;
  --title-fill: #321c45;
}

/* 활성 턴 인디케이터 */
.player-banner[data-active="true"] .player-banner-text {
  border-bottom: 2px solid var(--banner-accent);
}

/* 숨김 처리 */
.pb-layer-frame[hidden],
.pb-layer-badge[hidden],
.pb-layer-badgeframe[hidden],
.pb-title-plate[hidden] {
  display: none !important;
}

/* 7. 소형 화면 및 반응형 대응 (폭 280px 이하 칭호 숨김) */
@container (max-width: 280px) {
  .pb-name, .player-banner-name { font-size: 14px; }
  .pb-tier, .player-banner-detail { font-size: 11.5px; }
  .pb-title-plate { display: none !important; }
}

@media (max-width: 380px) {
  .pb-title-plate { display: none !important; }
}

/* 저높이 가로 화면 대응 */
@media (orientation: landscape) and (max-height: 500px) {
  .player-banner, .pb-card {
    width: 210px;
    padding: 0;
  }
  .pb-name, .player-banner-name { font-size: 13px; }
  .pb-tier, .player-banner-detail { font-size: 11px; }
  .pb-title-plate { display: none !important; }
  .pb-layer-content, .player-banner-text { gap: 2px; }
}

/* Keep decorative pixels within the card and preserve readable vertical spacing. */
.pb-layer-frame { overflow:hidden; border-radius:6px; }
.pb-layer-content, .player-banner-text { gap:6px; }

import type { BannerAppearance, BannerId } from "./banner-collection";
import {
  ownsBanner,
} from "./banner-progress";
import {
  loadMasterySnapshot,
  saveSnapshot,
  deviceId,
  earnedMedalCount,
  isMedalEarned,
  type MasteryId,
  type MasteryStorage,
} from "./mastery";

export type CosmeticSlot = "banner" | "frame" | "badge" | "badgeFrame" | "title" | "titleFrame";

export interface CosmeticLoadout {
  banner: BannerAppearance;
  frame: string | null;
  badge: string | null;
  badgeFrame: string | null;
  title: string | null;
  titleFrame: string | null;
}

export const COSMETIC_OPTIONS: Record<CosmeticSlot, readonly string[]> = {
  banner: [
    "classic",
    "slate",
    "forest",
    "banner_cosmic_knight",
    "banner_crimson_sun",
    "banner_hidden_myeongnyang",
  ],
  frame: ["frame:classic-gold", "frame:mastery-complete"],
  badge: [
    "badge:mastery-m01",
    "badge:mastery-m02",
    "badge:mastery-m03",
    "badge:mastery-m04",
    "badge:mastery-m05",
    "badge:mastery-m06",
    "badge:mastery-m07",
    "badge:mastery-m08",
  ],
  badgeFrame: ["badgeFrame:gold", "badgeFrame:silver", "badgeFrame:violet"],
  title: ["title:challenger", "title:explorer"],
  titleFrame: ["titleFrame:gold", "titleFrame:silver", "titleFrame:violet"],
};

export const DEFAULT_COSMETICS: Readonly<CosmeticLoadout> = Object.freeze({
  banner: "classic",
  frame: null,
  badge: null,
  badgeFrame: null,
  title: null,
  titleFrame: null,
});

export const GUEST_COSMETICS: Readonly<CosmeticLoadout> = Object.freeze({
  banner: "plain",
  frame: null,
  badge: null,
  badgeFrame: null,
  title: null,
  titleFrame: null,
});

function isStorageSafe(storage: MasteryStorage): boolean {
  if (!storage) return false;
  const owner = (storage as { owner?: string | null }).owner;
  const unsafe = (storage as { unsafeData?: boolean }).unsafeData;
  return (
    owner !== null &&
    owner !== undefined &&
    unsafe !== true &&
    (storage as { ready?: boolean }).ready !== false &&
    (storage as { conflict?: boolean }).conflict !== true
  );
}

export function ownsCosmetic(storage: MasteryStorage, slot: CosmeticSlot, id: string | null): boolean {
  if (!storage || (storage as { unsafeData?: boolean }).unsafeData === true) return false;
  const owner = (storage as { owner?: string | null }).owner;

  // Guest accounts cannot own or equip member cosmetics: guest plain only
  if (owner === null || owner === undefined) {
    return slot === "banner" && id === "plain";
  }

  // Member accounts
  if (id === null) {
    // Banner cannot be null; all other slots can be unequipped (null choice)
    return slot !== "banner";
  }

  if (!COSMETIC_OPTIONS[slot]?.includes(id)) {
    return false;
  }

  if (slot === "banner") {
    return ownsBanner(storage, id as BannerId);
  }

  if (slot === "frame") {
    if (id === "frame:classic-gold") return true;
    if (id === "frame:mastery-complete") {
      const snapshot = loadMasterySnapshot(storage);
      if (snapshot.malformed) return false;
      return Boolean(snapshot.rewards.items["frame:mastery-complete"]) || earnedMedalCount(snapshot.progress) >= 8;
    }
    return false;
  }

  if (slot === "badge") {
    const snapshot = loadMasterySnapshot(storage);
    if (snapshot.malformed) return false;
    const medalMatch = /^badge:mastery-(m0[1-8])$/.exec(id);
    if (!medalMatch) return false;
    const medalId = medalMatch[1].toUpperCase() as MasteryId;
    return Boolean(snapshot.rewards.items[id]) || isMedalEarned(snapshot.progress, medalId);
  }

  if (slot === "badgeFrame") {
    return ["badgeFrame:gold", "badgeFrame:silver", "badgeFrame:violet"].includes(id);
  }

  if (slot === "title") {
    if (id === "title:challenger") return true;
    if (id === "title:explorer") {
      const snapshot = loadMasterySnapshot(storage);
      if (snapshot.malformed) return false;
      return Boolean(snapshot.rewards.items["title:explorer"]) || earnedMedalCount(snapshot.progress) >= 4;
    }
    return false;
  }

  if (slot === "titleFrame") {
    return ["titleFrame:gold", "titleFrame:silver", "titleFrame:violet"].includes(id);
  }

  return false;
}

export function getCosmeticLoadout(storage: MasteryStorage): CosmeticLoadout {
  if (!storage || (storage as { owner?: string | null }).owner === null || (storage as { owner?: string | null }).owner === undefined) {
    return { ...GUEST_COSMETICS };
  }

  const snapshot = loadMasterySnapshot(storage);
  if (snapshot.malformed) {
    return { ...DEFAULT_COSMETICS };
  }

  let banner: BannerAppearance = "classic";
  const bannerItem = snapshot.preferences.equipped.banner?.itemId;
  if (bannerItem) {
    const raw = bannerItem.startsWith("banner:") ? bannerItem.slice(7) : bannerItem;
    if (ownsCosmetic(storage, "banner", raw)) {
      banner = raw as BannerId;
    }
  }

  const getSlotItem = (slot: "frame" | "badge" | "badgeFrame" | "title" | "titleFrame"): string | null => {
    const item = snapshot.preferences.equipped[slot]?.itemId ?? null;
    if (item && ownsCosmetic(storage, slot, item)) {
      return item;
    }
    return null;
  };

  return {
    banner,
    frame: getSlotItem("frame"),
    badge: getSlotItem("badge"),
    badgeFrame: getSlotItem("badgeFrame"),
    title: getSlotItem("title"),
    titleFrame: getSlotItem("titleFrame"),
  };
}

export function equipCosmeticLoadout(storage: MasteryStorage, loadout: CosmeticLoadout): boolean {
  if (!isStorageSafe(storage)) return false;
  if (!loadout || typeof loadout !== "object") return false;

  // Validate banner
  if (typeof loadout.banner !== "string" || loadout.banner === "plain" || !ownsCosmetic(storage, "banner", loadout.banner)) {
    return false;
  }

  // Validate other slots
  const nonBannerSlots = ["frame", "badge", "badgeFrame", "title", "titleFrame"] as const;
  for (const slot of nonBannerSlots) {
    const val = loadout[slot];
    if (val !== null && (typeof val !== "string" || !ownsCosmetic(storage, slot, val))) {
      return false;
    }
  }

  const snapshot = loadMasterySnapshot(storage);
  if (snapshot.malformed) return false;

  const now = new Date().toISOString();
  const devId = deviceId(storage);

  // Atomic update preserving tracked medal
  snapshot.preferences.equipped.banner = {
    itemId: `banner:${loadout.banner}`,
    updatedAt: now,
    deviceId: devId,
  };

  for (const slot of nonBannerSlots) {
    snapshot.preferences.equipped[slot] = {
      itemId: loadout[slot],
      updatedAt: now,
      deviceId: devId,
    };
  }

  saveSnapshot(storage, snapshot);
  return true;
}

export function normalizePublicCosmetics(value: unknown): CosmeticLoadout | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;

  const raw = value as Record<string, unknown>;
  const allowedKeys = ["banner", "frame", "badge", "badgeFrame", "title", "titleFrame"];
  if (Object.keys(raw).some(k => !allowedKeys.includes(k))) return null;

  let banner = raw.banner;
  if (typeof banner === "string" && banner.startsWith("banner:")) {
    banner = banner.slice(7);
  }

  if (banner === "plain") {
    // Guest combo: plain only with all other slots null
    for (const key of ["frame", "badge", "badgeFrame", "title", "titleFrame"]) {
      if (raw[key] !== null && raw[key] !== undefined) return null;
    }
    return { ...GUEST_COSMETICS };
  }

  if (typeof banner !== "string" || !COSMETIC_OPTIONS.banner.includes(banner)) {
    return null;
  }

  const validateSlot = (slot: "frame" | "badge" | "badgeFrame" | "title" | "titleFrame"): string | null | undefined => {
    const v = raw[slot];
    if (v === null || v === undefined) return null;
    if (typeof v === "string" && COSMETIC_OPTIONS[slot].includes(v)) return v;
    return undefined;
  };

  const frame = validateSlot("frame");
  if (frame === undefined) return null;
  const badge = validateSlot("badge");
  if (badge === undefined) return null;
  const badgeFrame = validateSlot("badgeFrame");
  if (badgeFrame === undefined) return null;
  const title = validateSlot("title");
  if (title === undefined) return null;
  const titleFrame = validateSlot("titleFrame");
  if (titleFrame === undefined) return null;

  return {
    banner: banner as BannerAppearance,
    frame,
    badge,
    badgeFrame,
    title,
    titleFrame,
  };
}

import { I18nManager, type LanguageCode } from './i18n';
import {
  bannerImageUrl,
  type BannerTheme,
} from './banner-collection';
import { getCosmeticsCopy } from './cosmetics-copy';
import './cosmetics-view.css';

import { DEFAULT_COSMETICS, GUEST_COSMETICS, getCosmeticLoadout, normalizePublicCosmetics, type CosmeticLoadout } from './cosmetics';
export { DEFAULT_COSMETICS, GUEST_COSMETICS, getCosmeticLoadout, normalizePublicCosmetics };
export type { CosmeticLoadout };

export const BOT_COSMETICS: CosmeticLoadout = {
  banner: 'classic',
  frame: null,
  badge: null,
  badgeFrame: null,
  title: null,
  titleFrame: null,
};

// 메달 배지 메타정보 및 글리프
export const COSMETIC_BADGE_META: Record<string, { glyph: string; hasImage: boolean }> = {
  'badge:mastery-m01': { glyph: '★', hasImage: true },
  'badge:mastery-m02': { glyph: '♘', hasImage: true },
  'badge:mastery-m03': { glyph: '🧩', hasImage: true },
  'badge:mastery-m04': { glyph: '♛', hasImage: true },
  'badge:mastery-m05': { glyph: '⚔', hasImage: true },
  'badge:mastery-m06': { glyph: '⚡', hasImage: true },
  'badge:mastery-m07': { glyph: '🛡', hasImage: true },
  'badge:mastery-m08': { glyph: '🏰', hasImage: true },
};

/**
 * 배지 ID에 대응하는 WebP 이미지 URL을 반환합니다.
 */
export function getCosmeticBadgeImage(badgeId: string | null, baseUrl?: string): string | null {
  if (!badgeId || badgeId === 'none') return null;
  const rawBase = baseUrl ?? import.meta.env?.BASE_URL ?? '/';
  const base = rawBase.endsWith('/') ? rawBase : `${rawBase}/`;

  const normalized = badgeId.toLowerCase().replace(/^badge:/, '');
  const match = normalized.match(/^(?:mastery-)?(m0[1-8])$/);
  if (match) {
    return `${base}assets/cosmetics/badge-${match[1]}.webp`;
  }
  if (normalized === 'first_victory') {
    return `${base}assets/cosmetics/badge-m01.webp`;
  }
  return null;
}

/**
 * 칭호 ID에 대응하는 9개 언어 현지화 텍스트를 반환합니다.
 */
export function getCosmeticTitleLabel(titleId: string | null, lang?: LanguageCode): string {
  if (!titleId) return '';
  const language: LanguageCode = lang || (I18nManager.getLanguage ? I18nManager.getLanguage() : 'en');
  const copy = getCosmeticsCopy(language);

  // 정규화된 키 탐색 (e.g., 'title:explorer', 'title:challenger')
  const normalizedKey = titleId.startsWith('title:') ? titleId : `title:${titleId}`;
  if (copy.options[normalizedKey]) {
    return copy.options[normalizedKey];
  }
  if (copy.options[titleId]) {
    return copy.options[titleId];
  }

  // i18n 엔진 직접 조회
  const i18nLookup = I18nManager.t?.(`cosmetics.${titleId.replace(/^title:/, '')}`);
  if (i18nLookup && !i18nLookup.startsWith('cosmetics.')) {
    return i18nLookup;
  }

  // 안전한 기본값 반환
  if (normalizedKey.includes('explorer') || titleId.includes('explorer')) {
    return copy.options['title:explorer'] || (language === 'ko' ? '탐험가' : 'Explorer');
  }
  return copy.options['title:challenger'] || (language === 'ko' ? '도전자' : 'Challenger');
}

/**
 * 배지 ID에 대응하는 9개 언어 레이블을 반환합니다.
 */
export function getCosmeticBadgeLabel(badgeId: string | null, lang?: LanguageCode): string {
  if (!badgeId) return '';
  const language: LanguageCode = lang || (I18nManager.getLanguage ? I18nManager.getLanguage() : 'en');
  const copy = getCosmeticsCopy(language);
  const normalizedKey = badgeId.startsWith('badge:') ? badgeId : `badge:mastery-${badgeId.toLowerCase()}`;

  if (copy.options[normalizedKey]) {
    return copy.options[normalizedKey];
  }
  if (copy.options[badgeId]) {
    return copy.options[badgeId];
  }

  return language === 'ko' ? '숙련 배지' : 'Mastery Badge';
}

/**
 * 배지 ID에 대응하는 네이티브 체스/문양 글리프를 반환합니다.
 */
export function getCosmeticBadgeGlyph(badgeId: string | null): string {
  if (!badgeId) return '';
  const normalizedKey = badgeId.startsWith('badge:') ? badgeId : `badge:mastery-${badgeId.toLowerCase()}`;
  const meta = COSMETIC_BADGE_META[normalizedKey] || COSMETIC_BADGE_META[badgeId];
  return meta ? meta.glyph : '★';
}

export interface CosmeticCardView {
  card: HTMLElement;
  bgLayer: HTMLElement;
  frameLayer: HTMLElement;
  frameImg: HTMLImageElement;
  frameFallback: HTMLElement;
  badgeLayer: HTMLElement;
  badgeImg: HTMLImageElement;
  badgeGlyph: HTMLElement;
  badgeFrameLayer: HTMLElement;
  titlePlate: HTMLElement;
}

/**
 * 단일 카드 DOM 내부에 필요한 코스메틱 레이어 요소를 생성하거나 검색하여 바인딩합니다.
 */
export function createCosmeticCardElements(card: HTMLElement): CosmeticCardView {
  let bgLayer = card.querySelector<HTMLElement>(':scope > .pb-layer-background');
  if (!bgLayer) {
    bgLayer = document.createElement('div');
    bgLayer.className = 'pb-layer-background';
    bgLayer.setAttribute('aria-hidden', 'true');
    card.prepend(bgLayer);
  }

  let frameLayer = card.querySelector<HTMLElement>(':scope > .pb-layer-frame');
  let frameImg = frameLayer?.querySelector<HTMLImageElement>(':scope > .pb-frame-img') ?? null;
  let frameFallback = frameLayer?.querySelector<HTMLElement>(':scope > .pb-frame-fallback') ?? null;

  if (!frameLayer) {
    frameLayer = document.createElement('div');
    frameLayer.className = 'pb-layer-frame';
    frameLayer.setAttribute('aria-hidden', 'true');

    frameImg = document.createElement('img');
    frameImg.className = 'pb-frame-img';
    frameImg.alt = '';
    frameImg.src = (import.meta.env?.BASE_URL || '/') + 'assets/cosmetics/classic-frame.webp';

    frameFallback = document.createElement('div');
    frameFallback.className = 'pb-frame-fallback';

    frameImg.onerror = () => {
      if (frameImg) frameImg.style.display = 'none';
      if (frameFallback) frameFallback.style.display = 'block';
    };
    frameImg.onload = () => {
      if (frameImg) frameImg.style.display = 'block';
      if (frameFallback) frameFallback.style.display = 'none';
    };

    frameLayer.append(frameImg, frameFallback);
    card.append(frameLayer);
  }

  let badgeLayer = card.querySelector<HTMLElement>(':scope > .pb-layer-badge');
  let badgeImg = badgeLayer?.querySelector<HTMLImageElement>(':scope > .pb-badge-img') ?? null;
  let badgeGlyph = badgeLayer?.querySelector<HTMLElement>(':scope > .pb-badge-glyph') ?? null;

  if (!badgeLayer) {
    badgeLayer = document.createElement('div');
    badgeLayer.className = 'pb-layer-badge';

    badgeImg = document.createElement('img');
    badgeImg.className = 'pb-badge-img';
    badgeImg.alt = '';

    badgeGlyph = document.createElement('span');
    badgeGlyph.className = 'pb-badge-glyph';
    badgeGlyph.setAttribute('aria-hidden', 'true');

    badgeLayer.append(badgeImg, badgeGlyph);
    card.append(badgeLayer);
  }

  let badgeFrameLayer = card.querySelector<HTMLElement>(':scope > .pb-layer-badgeframe');
  if (!badgeFrameLayer) {
    badgeFrameLayer = document.createElement('div');
    badgeFrameLayer.className = 'pb-layer-badgeframe';
    badgeFrameLayer.setAttribute('aria-hidden', 'true');
    card.append(badgeFrameLayer);
  }

  let titlePlate = card.querySelector<HTMLElement>('.pb-title-plate');
  if (!titlePlate) {
    titlePlate = document.createElement('span');
    titlePlate.className = 'pb-title-plate';
    const textContainer = card.querySelector('.player-banner-text') || card.querySelector('.pb-layer-content') || card;
    textContainer.append(titlePlate);
  }

  return {
    card,
    bgLayer,
    frameLayer,
    frameImg: frameImg!,
    frameFallback: frameFallback!,
    badgeLayer,
    badgeImg: badgeImg!,
    badgeGlyph: badgeGlyph!,
    badgeFrameLayer,
    titlePlate,
  };
}

/**
 * 코스메틱 뷰를 주어진 loadout 데이터에 따라 가볍고 안전하게 갱신합니다.
 */
export function updateCosmeticCard(
  view: CosmeticCardView,
  loadout: CosmeticLoadout,
  titleLabel?: string,
): void {
  const { card, bgLayer, frameLayer, badgeLayer, badgeImg, badgeGlyph, badgeFrameLayer, titlePlate } = view;

  const hasFrame = Boolean(loadout.frame && loadout.frame !== 'none');
  const hasBadge = Boolean(loadout.badge && loadout.badge !== 'none');
  const hasBadgeFrame = hasBadge && Boolean(loadout.badgeFrame && loadout.badgeFrame !== 'none');
  const hasTitle = Boolean(loadout.title && loadout.title !== 'none');

  // 1. 테마 및 배경
  card.dataset.theme = loadout.banner;
  card.dataset.hasFrame = String(hasFrame);
  card.dataset.badgeVisible = String(hasBadge);

  if (loadout.banner === 'plain') {
    bgLayer.style.backgroundImage = 'none';
  } else {
    const url = bannerImageUrl(loadout.banner as BannerTheme);
    bgLayer.style.backgroundImage = `url("${url}")`;
  }

  // 2. 외곽 프레임
  frameLayer.hidden = !hasFrame;
  if (hasFrame && loadout.frame === 'frame:mastery-complete') {
    card.dataset.frameStyle = 'mastery-complete';
  } else {
    delete card.dataset.frameStyle;
  }

  // 3. 배지 및 배지 프레임
  badgeLayer.hidden = !hasBadge;
  badgeFrameLayer.hidden = !hasBadgeFrame;

  if (hasBadge && loadout.badge) {
    const currentBadgeId = loadout.badge;
    const badgeLabel = getCosmeticBadgeLabel(currentBadgeId);
    badgeLayer.setAttribute('aria-label', badgeLabel);
    badgeLayer.title = badgeLabel;

    const imgSrc = getCosmeticBadgeImage(currentBadgeId);
    if (imgSrc) {
      if (badgeImg.dataset.activeBadge !== currentBadgeId) {
        delete badgeImg.dataset.failed;
        badgeImg.dataset.activeBadge = currentBadgeId;
      }
      const failed = badgeImg.dataset.failed === 'true';
      badgeGlyph.textContent = getCosmeticBadgeGlyph(currentBadgeId);
      badgeImg.style.display = failed ? 'none' : 'block';
      badgeGlyph.style.display = failed ? 'flex' : 'none';

      badgeImg.onload = () => {
        if (badgeImg.dataset.activeBadge !== currentBadgeId) return;
        delete badgeImg.dataset.failed;
        badgeImg.style.display = 'block';
        badgeGlyph.style.display = 'none';
      };
      badgeImg.onerror = () => {
        if (badgeImg.dataset.activeBadge !== currentBadgeId) return;
        badgeImg.dataset.failed = 'true';
        badgeImg.style.display = 'none';
        badgeGlyph.style.display = 'flex';
        badgeGlyph.textContent = getCosmeticBadgeGlyph(currentBadgeId);
      };

      if (badgeImg.getAttribute('src') !== imgSrc) {
        badgeImg.src = imgSrc;
      }
    } else {
      badgeImg.onload = null;
      badgeImg.onerror = null;
      delete badgeImg.dataset.activeBadge;
      delete badgeImg.dataset.failed;
      badgeImg.removeAttribute('src');
      badgeImg.style.display = 'none';
      badgeGlyph.style.display = 'flex';
      badgeGlyph.textContent = getCosmeticBadgeGlyph(currentBadgeId);
    }
  } else {
    badgeImg.onload = null;
    badgeImg.onerror = null;
    delete badgeImg.dataset.activeBadge;
    delete badgeImg.dataset.failed;
    badgeImg.removeAttribute('src');
    badgeImg.style.display = 'none';
    badgeGlyph.style.display = 'none';
  }

  if (hasBadgeFrame) {
    badgeFrameLayer.dataset.frame = loadout.badgeFrame?.split(':').at(-1) || 'none';
  }

  // 4. 칭호 플레이트
  titlePlate.hidden = !hasTitle;
  if (hasTitle) {
    const label = titleLabel || getCosmeticTitleLabel(loadout.title);
    titlePlate.textContent = label;
    titlePlate.title = label;
    titlePlate.dataset.frame = loadout.titleFrame?.split(':').at(-1) || 'none';
  } else {
    titlePlate.textContent = '';
  }
}

/**
 * 외부 모듈(설정 UI 등)에서 재사용 가능한 경량 외형 적용 함수
 */
export function applyCosmeticAppearance(
  card: HTMLElement,
  loadout: CosmeticLoadout,
  titleLabel?: string,
): void {
  const view = createCosmeticCardElements(card);
  updateCosmeticCard(view, loadout, titleLabel);
}

