import { I18nManager, type LanguageCode } from "./i18n";
import { progressStorage } from "./progress-storage";
import {
  BANNER_IDS,
  BANNER_THEMES,
  DEFAULT_BANNER_IDS,
  ACHIEVEMENT_BANNER_IDS,
  isValidTheme,
  isValidBannerAppearance,
  equipBanner,
  ownsBanner,
  getBannerProgress,
  bannerImageUrl,
  preloadEquippedBanner as preloadEquippedBannerHelper,
  type BannerId,
  type BannerTheme,
  type BannerAppearance,
} from "./banner-collection";
import { bannerCopy, bannerThemeName } from "./banner-copy";
import { DEFAULT_COSMETICS, GUEST_COSMETICS, getCosmeticLoadout, normalizePublicCosmetics, type CosmeticLoadout } from "./cosmetics";

export type { BannerId, BannerTheme, BannerAppearance };
export {
  BANNER_IDS,
  BANNER_THEMES,
  DEFAULT_BANNER_IDS,
  ACHIEVEMENT_BANNER_IDS,
  isValidTheme,
  isValidBannerAppearance,
  ownsBanner,
  getBannerProgress,
  bannerImageUrl,
};

const listeners = new Set<() => void>();

// Visual preview only: never grant rewards or save the selection to an account.
export const isLocalBannerPreview = Boolean(import.meta.env?.DEV)
  && typeof location !== "undefined"
  && ["localhost", "127.0.0.1", "[::1]"].includes(location.hostname)
  && new URLSearchParams(location.search).get("bannerPreview") === "1";
let previewTheme: BannerTheme = "classic";
let previewCosmetics: CosmeticLoadout = { ...DEFAULT_COSMETICS };
let cachedCosmetics: CosmeticLoadout | null = null;
let cachedOwner: string | null = null;

export function getPlayerCosmetics(isMember: boolean): CosmeticLoadout {
  if (isLocalBannerPreview) return { ...previewCosmetics, banner: previewTheme };
  if (!isMember) return { ...GUEST_COSMETICS };
  if (!cachedCosmetics || cachedOwner !== progressStorage.owner) {
    cachedCosmetics = getCosmeticLoadout(progressStorage);
    cachedOwner = progressStorage.owner;
  }
  return { ...cachedCosmetics };
}

export function setLocalCosmeticPreview(value: CosmeticLoadout): boolean {
  if (!isLocalBannerPreview) return false;
  const normalized = normalizePublicCosmetics(value);
  if (!normalized || normalized.banner === 'plain') return false;
  previewCosmetics = normalized;
  previewTheme = normalized.banner;
  listeners.forEach(listener => listener());
  return true;
}


// Listen to progressStorage updates so account changes automatically trigger banner theme listeners
if (typeof progressStorage?.subscribe === "function") {
  progressStorage.subscribe(() => {
    cachedCosmetics = null;
    if (progressStorage.owner && progressStorage.ready) preloadEquippedBanner();
    listeners.forEach((listener) => {
      try {
        listener();
      } catch (err) {
        console.error("Error in banner theme progress observer:", err);
      }
    });
  });
}

/**
 * Returns player banner appearance.
 * Guests always receive "plain".
 * Members receive their equipped account banner theme.
 */
export function getPlayerBannerTheme(isMember: boolean): BannerAppearance {
  return isMember || isLocalBannerPreview ? getBannerTheme() : "plain";
}

/**
 * Retrieves the currently active banner theme for the user.
 * Defaults to "classic".
 */
export function getBannerTheme(): BannerTheme {
  if (isLocalBannerPreview) return previewTheme;
  if (progressStorage?.owner) {
    const banner = getPlayerCosmetics(true).banner;
    return banner === 'plain' ? 'classic' : banner;
  }
  return "classic";
}

/**
 * Sets the banner theme on the member's account.
 */
export function setBannerTheme(theme: BannerTheme): void {
  if (!isValidTheme(theme)) {
    return;
  }
  if (isLocalBannerPreview) {
    previewTheme = theme;
  } else if (progressStorage?.owner) {
    const success = equipBanner(progressStorage, theme);
    if (!success) {
      // If equipping failed because banner is locked or invalid, return early
      return;
    }
  } else {
    return;
  }

  listeners.forEach((listener) => {
    try {
      listener();
    } catch (err) {
      console.error("Error in banner theme listener:", err);
    }
  });
}

/**
 * Subscribes to banner theme updates.
 */
export function subscribeBannerTheme(listener: () => void): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Returns the localized name for a banner theme.
 */
export function bannerThemeLabel(theme: BannerTheme, lang?: LanguageCode): string {
  const language = lang || I18nManager.getLanguage?.() || "en";
  return bannerThemeName(theme, language);
}

/**
 * Returns localized banner settings text ("tab" or "hint").
 */
export function bannerSettingsText(key: "tab" | "hint", lang?: LanguageCode): string {
  const language = lang || I18nManager.getLanguage?.() || "en";
  const dict = bannerCopy(language);
  return dict[key] || "";
}

/**
 * Preloads the equipped banner image for fast rendering.
 */
export function preloadEquippedBanner(baseUrl?: string): void {
  preloadEquippedBannerHelper(progressStorage, baseUrl);
}

/* ==========================================================================
   플레이어 배너 스타일 (Player Banner CSS)
   - 6슬롯 코스메틱 완벽 통합
   - 친구 추가 버튼 오버랩 방지 및 모바일 반응형
   ========================================================================== */

.player-banners {
  position: absolute;
  inset: 0;
  z-index: 9;
  pointer-events: none;
  user-select: none;
}
.player-banners[hidden] {
  display: none;
}

.player-banner {
  --banner-ink: #302418;
  --banner-accent: #795520;
  --banner-bg: #eee2c9;
  position: absolute;
  display: flex;
  align-items: center;
  width: min(330px, calc(100vw - 28px));
  aspect-ratio: 3 / 1;
  box-sizing: border-box;
  color: var(--banner-ink);
  border: 0;
  border-radius: 6px;
  pointer-events: none;
  container-type: inline-size;
}

/* A confirmed loss, not a win cue; no layout shift or flashing animation. */
.player-banner.piece-loss { outline: 2px solid #d9ad6b; outline-offset: -2px; }

/* 6개 기본 테마별 설정 */
.player-banner[data-theme="slate"] {
  --banner-ink: #172c43;
  --banner-accent: #35506e;
  --banner-bg: #dce5f0;
}
.player-banner[data-theme="forest"] {
  --banner-ink: #25351e;
  --banner-accent: #3d542d;
  --banner-bg: #e1e7cb;
}
.player-banner[data-theme="banner_cosmic_knight"] {
  --banner-ink: #f8fafc;
  --banner-accent: #818cf8;
  --banner-bg: #0f172a;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
}
.player-banner[data-theme="banner_crimson_sun"] {
  --banner-ink: #fff1f2;
  --banner-accent: #fb7185;
  --banner-bg: #1c1917;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
}
.player-banner[data-theme="banner_hidden_myeongnyang"] {
  --banner-ink: #f0fdfa;
  --banner-accent: #2dd4bf;
  --banner-bg: #042f2e;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
}
.player-banner[data-theme="plain"] {
  --banner-ink: #f1f5f9;
  --banner-accent: #94a3b8;
  --banner-bg: #273344;
}

/* 위치 지정 */
.player-banner[data-owner="opponent"] {
  top: 54px;
  left: 14px;
}
.player-banner[data-owner="self"] {
  bottom: calc(14px + env(safe-area-inset-bottom, 0px));
  right: 14px;
}

/* 기물 엠블럼 (접근성 및 스크린리더용) */
.player-banner-emblem {
  display: none;
}

/* 친구 추가 버튼 (우측 상단/우측단 오버랩 방지) */
.player-banner-add {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  pointer-events: auto;
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  padding: 0;
  border: 1px solid var(--banner-accent);
  border-radius: 6px;
  background: var(--banner-bg);
  color: var(--banner-ink);
  font-size: 22px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
  transition: transform 0.1s ease, background-color 0.15s ease;
}
.player-banner-add:hover:not(:disabled) {
  transform: translateY(-50%) scale(1.05);
}
.player-banner-add[hidden] {
  display: none !important;
}
.player-banner-add:disabled {
  cursor: default;
  opacity: 0.7;
}
.player-banner-add:focus-visible {
  outline: 2px solid var(--banner-ink);
  outline-offset: 2px;
}

/* 친구 추가 버튼이 활성화된 경우 텍스트 영역 우측 패딩 확보 (오버랩 완벽 방지) */
.player-banner[data-owner="opponent"]:has(.player-banner-add:not([hidden])) .player-banner-text {
  right: 52px;
}

/* 상태 메시지 말풍선 */
.player-banner-status {
  position: absolute;
  top: 100%;
  left: 0;
  margin: 5px 0 0;
  max-width: 100%;
  padding: 8px;
  background: var(--banner-bg);
  color: var(--banner-ink);
  border: 1px solid var(--banner-accent);
  border-radius: 6px;
  font-size: 12px;
  line-height: 1.4;
  pointer-events: none;
  z-index: 11;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}
.player-banner-status[hidden] {
  display: none !important;
}

/* 모바일 및 화면 크기별 브레이크포인트 */
@media (max-width: 600px) {
  .player-banner {
    width: min(270px, calc(100vw - 20px));
  }
  .player-banner[data-owner="opponent"] {
    top: 50px;
    left: 10px;
  }
  .player-banner[data-owner="self"] {
    bottom: calc(10px + env(safe-area-inset-bottom, 0px));
    right: 10px;
  }
  .player-banner-name {
    font-size: 14px;
  }
  .player-banner-detail {
    font-size: 11.5px;
  }
  .player-banner-add {
    width: 32px;
    height: 32px;
    font-size: 18px;
    right: 6px;
  }
  .player-banner[data-owner="opponent"]:has(.player-banner-add:not([hidden])) .player-banner-text {
    right: 42px;
  }
}

@media (max-width: 1050px) {
  .player-banners:not([hidden]) ~ .turn-hud-container > .mastery-hud-objective {
    position: absolute;
    top: 145px;
    width: max-content;
  }
}

/* 저높이 가로 화면 대응 */
@media (orientation: landscape) and (max-height: 500px) {
  .player-banner {
    width: 210px;
    aspect-ratio: 3 / 1;
  }
  .player-banner-name {
    font-size: 13px;
  }
  .player-banner-detail {
    font-size: 11px;
  }
  .player-banner-add {
    width: 30px;
    height: 30px;
    font-size: 16px;
    right: 4px;
  }
  .player-banner[data-owner="opponent"]:has(.player-banner-add:not([hidden])) .player-banner-text {
    right: 38px;
  }
}

@media (max-width: 380px) and (orientation: portrait) {
  .player-banner[data-owner="opponent"] {
    top: 92px;
  }
}

@media (orientation: landscape) and (max-height: 500px) and (max-width: 740px) {
  .player-banner {
    width: 180px;
  }
  .player-banner[data-owner="self"] {
    bottom: calc(4px + env(safe-area-inset-bottom, 0px));
  }
}

import { getPlayerCosmetics } from './banner-theme';
import { I18nManager } from './i18n';
import { formatTier } from './tier-view';
import { getRuntimeText } from './runtime-text';
import { getBannerTheme, subscribeBannerTheme, type BannerAppearance } from './banner-theme';
import { progressStorage } from './progress-storage';
import {
  type CosmeticLoadout,
  DEFAULT_COSMETICS,
  GUEST_COSMETICS,
  BOT_COSMETICS,
  getCosmeticLoadout,
  getCosmeticTitleLabel,
  createCosmeticCardElements,
  updateCosmeticCard,
  applyCosmeticAppearance,
  normalizePublicCosmetics,
  type CosmeticCardView,
} from './cosmetics-view';
import type { UserProfile } from './supabase-auth';
import type { PieceSide } from './layout';
import type { GameMode } from './game-mode';
import './player-banner.css';

export type { CosmeticLoadout, CosmeticCardView };
export {
  DEFAULT_COSMETICS,
  GUEST_COSMETICS,
  BOT_COSMETICS,
  getCosmeticLoadout,
  getCosmeticTitleLabel,
  createCosmeticCardElements,
  updateCosmeticCard,
  applyCosmeticAppearance,
  normalizePublicCosmetics,
};

export interface PlayerBannerState {
  visible: boolean;
  mode: GameMode;
  stage: number;
  currentSide: PieceSide;
  mySide: PieceSide | null;
  profile: UserProfile | null;
  opponent: { id: string; nickname: string; mmr: number } | null;
  opponentDisplayName?: string;
  rankedMode: 'classic' | 'strategy';
  loggedIn: boolean;
  opponentBannerTheme?: BannerAppearance;
  opponentCosmetics?: CosmeticLoadout;
  remaining?: Record<PieceSide, number>;
}

export function getPlayerBannerModels(state: PlayerBannerState) {
  const mine = state.mode === 'online' ? state.mySide ?? 'white' : 'white';
  const opposite = mine === 'white' ? 'black' : 'white';
  const profile = state.profile;
  const rating = state.rankedMode === 'strategy' && state.mode === 'online' ? profile?.strategyMmr : profile?.classicMmr;
  const self = {
    side: mine,
    name: profile?.nickname || I18nManager.t('online.guest_mode'),
    detail: state.loggedIn && rating !== undefined ? formatTier(rating) : I18nManager.t('online.guest_mode'),
    bot: false,
  };
  const opponent = state.mode === 'stage'
    ? { side: opposite, name: 'AI', detail: I18nManager.t('lobby.stage_label', { stage: state.stage }), bot: true }
    : state.mode === 'online'
      ? { side: opposite, name: state.opponent?.nickname || state.opponentDisplayName || getRuntimeText('matchmaking.default_opponent_name'),
          detail: state.opponent ? formatTier(state.opponent.mmr) : I18nManager.t('p2p.subtitle'), bot: false }
      : { side: opposite, name: I18nManager.t('ingame.turn_black'), detail: I18nManager.t('lobby.mode_2p_short'), bot: false };
  return {
    self,
    opponent,
    canAddFriend: state.mode === 'online' && state.loggedIn && !!profile &&
      !!state.opponent && state.opponent.id !== profile.id,
  };
}

export function createPlayerBanners(parent: HTMLElement, options: {
  getState: () => PlayerBannerState;
  requestFriend: (profileId: string, opponent: NonNullable<PlayerBannerState['opponent']>) => Promise<{ success: boolean; error?: string }>;
}) {
  const element = document.createElement('div');
  element.className = 'player-banners';
  element.hidden = true;

  const makeCard = (mine: boolean) => {
    const card = document.createElement('section');
    card.className = 'player-banner';
    card.dataset.owner = mine ? 'self' : 'opponent';

    const emblem = document.createElement('span');
    emblem.className = 'player-banner-emblem';
    emblem.setAttribute('aria-hidden', 'true');

    const text = document.createElement('div');
    text.className = 'player-banner-text';

    const name = document.createElement('strong');
    name.className = 'player-banner-name';

    const detail = document.createElement('span');
    detail.className = 'player-banner-detail';

    text.append(name, detail);
    card.append(emblem, text);
    element.append(card);

    // 6슬롯 코스메틱 DOM 엘리먼트 바인딩
    const cosmeticView = createCosmeticCardElements(card);

    const compact = document.createElement('span');
    compact.className = 'player-banner-compact';
    card.append(compact);

    return { card, emblem, name, detail, cosmeticView, compact };
  };

  const self = makeCard(true);
  const opponent = makeCard(false);

  const add = document.createElement('button');
  add.type = 'button';
  add.className = 'player-banner-add';

  const status = document.createElement('p');
  status.className = 'player-banner-status';
  status.setAttribute('role', 'status');
  status.hidden = true;

  opponent.card.append(add, status);
  parent.append(element);

  const completed = new Set<string>();
  const pending = new Set<string>();
  const messages = new Map<string, { key: string; name: string }>();
  let last = '';
  let destroyed = false;
  const lossUntil = { white: 0, black: 0 };

  const update = () => {
    if (destroyed) return;
    const state = options.getState();
    const hidden = !state.visible || !['stage', 'online', 'hotseat'].includes(state.mode);
    if (element.hidden !== hidden) element.hidden = hidden;
    const models = getPlayerBannerModels(state);
    for (const [view, model] of [[self, models.self], [opponent, models.opponent]] as const) {
      view.card.classList.toggle('piece-loss', !element.hidden && performance.now() < lossUntil[model.side as PieceSide]);
    }
    if (element.hidden) return;

    const key = `${state.profile?.id}:${state.opponent?.id}`;

    // 코스메틱 로드아웃 계산
    const selfCosmetics = getPlayerCosmetics(state.loggedIn);

    let opponentCosmetics: CosmeticLoadout;
    if (state.mode === 'stage') {
      opponentCosmetics = { ...BOT_COSMETICS };
    } else if (state.mode === 'hotseat') {
      opponentCosmetics = { ...GUEST_COSMETICS };
    } else if (state.opponentCosmetics) {
      opponentCosmetics = normalizePublicCosmetics(state.opponentCosmetics) ?? { ...GUEST_COSMETICS };
    } else if (state.opponentBannerTheme) {
      opponentCosmetics = {
        banner: state.opponentBannerTheme,
        frame: null,
        badge: null,
        badgeFrame: null,
        title: null,
        titleFrame: null,
      };
    } else {
      opponentCosmetics = { ...BOT_COSMETICS };
    }

    const signature = JSON.stringify([
      state,
      I18nManager.getLanguage?.() || 'ko',
      getBannerTheme(),
      selfCosmetics,
      opponentCosmetics,
      pending.has(key),
      completed.has(key),
      messages.get(key),
    ]);

    if (signature === last) return;
    last = signature;

    for (const [view, model] of [[self, models.self], [opponent, models.opponent]] as const) {
      const side = I18nManager.t(model.side === 'white' ? 'ingame.turn_white' : 'ingame.turn_black');
      const count = state.remaining?.[model.side as PieceSide];
      const label = [count === undefined ? '' : `${model.side === 'white' ? '♙' : '♟'} ${count}`, model.name, side, ...(model.bot ? [model.detail] : [])].filter(Boolean).join(' · ');
      view.compact.textContent = label;
      view.compact.title = label;
    }

    // 내 배너 렌더링
    self.name.textContent = models.self.name;
    self.name.title = models.self.name;
    self.detail.textContent = [models.self.detail, state.remaining ? `${models.self.side === 'white' ? '♙' : '♟'} ${state.remaining[models.self.side as PieceSide]}` : ''].filter(Boolean).join(' · ');
    self.emblem.textContent = models.self.bot ? '♚' : models.self.side === 'white' ? '♙' : '♟';
    self.card.dataset.active = String(models.self.side === state.currentSide);
    updateCosmeticCard(self.cosmeticView, selfCosmetics);
    self.card.setAttribute('aria-label', `${models.self.name} · ${self.detail.textContent}`);

    // 상대 배너 렌더링
    opponent.name.textContent = models.opponent.name;
    opponent.name.title = models.opponent.name;
    opponent.detail.textContent = [models.opponent.detail, state.remaining ? `${models.opponent.side === 'white' ? '♙' : '♟'} ${state.remaining[models.opponent.side as PieceSide]}` : ''].filter(Boolean).join(' · ');
    opponent.emblem.textContent = models.opponent.bot ? '♚' : models.opponent.side === 'white' ? '♙' : '♟';
    opponent.card.dataset.active = String(models.opponent.side === state.currentSide);
    updateCosmeticCard(opponent.cosmeticView, opponentCosmetics);
    opponent.card.setAttribute('aria-label', `${models.opponent.name} · ${opponent.detail.textContent}`);

    // 친구 추가 버튼 및 상태
    add.hidden = !models.canAddFriend;
    add.disabled = pending.has(key) || completed.has(key);
    add.textContent = completed.has(key) ? '✓' : pending.has(key) ? '…' : '+';
    add.title = I18nManager.t('friends.tab_add') ? I18nManager.t(completed.has(key) ? 'friends.request_already_sent' : 'friends.tab_add') : '+';
    add.setAttribute('aria-label', add.title);

    const message = messages.get(key);
    status.hidden = !models.canAddFriend || !message;
    status.textContent = message ? I18nManager.t(message.key, { name: message.name }) : '';
  };

  add.addEventListener('click', async () => {
    const state = options.getState();
    const target = state.opponent;
    if (!state.visible || !getPlayerBannerModels(state).canAddFriend || !state.profile || !target) return;
    const key = `${state.profile.id}:${target.id}`;
    if (pending.has(key) || completed.has(key)) return;

    pending.add(key);
    messages.delete(key);
    update();

    try {
      const result = await options.requestFriend(state.profile.id, target);
      if (result.success || result.error === 'request_already_sent') completed.add(key);
      const known = ['request_already_sent', 'user_not_found', 'cannot_add_self', 'login_required'];
      const message = result.success ? 'friends.request_sent_success' : known.includes(result.error ?? '') ? `friends.${result.error}` : 'online.server_error_fallback';
      messages.set(key, { key: message, name: target.nickname });
    } catch {
      messages.set(key, { key: 'online.server_error_fallback', name: target.nickname });
    } finally {
      pending.delete(key);
      update();
    }
  });

  const unsubscribeTheme = subscribeBannerTheme(update);
  const unsubscribeLanguage = I18nManager.subscribe(update);
  const unsubscribeProgress = typeof progressStorage?.subscribe === 'function'
    ? progressStorage.subscribe(update)
    : () => {};

  return {
    element,
    update,
    pieceRemoved(side: PieceSide) { lossUntil[side] = performance.now() + 280; update(); },
    resetFeedback() { lossUntil.white = 0; lossUntil.black = 0; update(); },
    destroy() {
      destroyed = true;
      unsubscribeTheme();
      unsubscribeLanguage();
      unsubscribeProgress();
      element.remove();
    },
  };
}

